/** WebP siblings under public/demo-media/optimized/ (generated by scripts/optimize-images.mjs). */

/** Width suffixes actually emitted by scripts/optimize-images.mjs (WIDTH_VARIANTS). */
export const DEMO_MEDIA_WIDTH_VARIANTS = [240, 280, 400, 480, 560, 640, 720, 960, 1200, 1440] as const;

const WIDTH_VARIANT_SET = new Set<number>(DEMO_MEDIA_WIDTH_VARIANTS);

function optimizedBase(src: string): string | undefined {
  if (!src.startsWith("/demo-media/") || src.includes("/optimized/")) {
    return undefined;
  }
  const rel = src.slice("/demo-media/".length);
  if (rel.includes("/")) {
    return undefined;
  }
  const withoutExt = src.replace(/\.(jpe?g|png)$/i, "");
  if (withoutExt === src) {
    return undefined;
  }
  return withoutExt.replace("/demo-media/", "/demo-media/optimized/");
}

/** Default single WebP (legacy max-edge export). */
export function demoMediaWebpSrc(src: string): string | undefined {
  const base = optimizedBase(src);
  return base ? `${base}.webp` : undefined;
}

/** Width-specific WebP (`…/optimized/foo-480w.webp`). */
export function demoMediaWebpAtWidth(src: string, width: number): string | undefined {
  const base = optimizedBase(src);
  return base ? `${base}-${width}w.webp` : undefined;
}

function knownWidthVariants(widths: readonly number[]): number[] {
  return widths.filter((w) => WIDTH_VARIANT_SET.has(w));
}

export function demoMediaSrcSet(src: string, widths: readonly number[]): string | undefined {
  const parts = knownWidthVariants(widths)
    .map((w) => {
      const url = demoMediaWebpAtWidth(src, w);
      return url ? `${url} ${w}w` : null;
    })
    .filter(Boolean);
  if (parts.length === 0) {
    const fallback = demoMediaWebpSrc(src);
    return fallback ? `${fallback} 1x` : undefined;
  }
  return parts.join(", ");
}

/** Smallest variant for `src` / preload (falls back to raster). */
export function demoMediaPreferredSrc(src: string, widths: readonly number[]): string {
  const sorted = [...knownWidthVariants(widths)].sort((a, b) => a - b);
  for (const w of sorted) {
    const url = demoMediaWebpAtWidth(src, w);
    if (url) return url;
  }
  return demoMediaWebpSrc(src) ?? src;
}
